fn main() {
    let numbers = [360, 97, 1024, 561, 143, 2003];
    let mut primes_count = 0;
    for &num in &numbers {
        println!("{}", num);
        let (divisors, sum, max) = find_divisors(num);
        println!("{}", divisors.len());
        println!("{}", sum);
        println!("{}", max);
        if is_prime(num) {
            println!("true");
            primes_count += 1;
        } else {
            println!("false");
        }
    }
    println!("{}", primes_count);
}
fn find_divisors(n: u32) -> (Vec<u32>, u32, u32) {
    let mut divisors = Vec::new();
    let mut sum = 0;
    let mut max = 0;
    for i in 2..=n {
        if n % i == 0 {
            divisors.push(i);
            sum += i;
            max = i;
        }
    }
    (divisors, sum, max)
}
fn is_prime(n: u32) -> bool {
    if n <= 1 {
        return false;
    }
    for i in 2..=((n as f64).sqrt() as u32) {
        if n % i == 0 {
            return false;
        }
    }
    true
}

